from math import comb

def sign(v):
    return (v > 0) - (v < 0)

def run_d1(xs, ys, ub):
    candidates=[]
    scores=0
    for sense in [1,-1]:
        for k,anchor in enumerate(xs):
            w=(-sense,sense/anchor)
            def prediction(x):
                v=w[0]+w[1]*x
                return 0 if abs(v)<1e-8 else sign(v)
            pred=[prediction(x) for x in xs[:k+1]]
            scores+=k+1
            loss=sum(p"'!=y for p,y in zip(pred,ys[:k+1]) if p!=0)
            if loss > ub:
                continue
            for x,y in zip(xs[k+1:],ys[k+1:]):
                p=prediction(x)
                scores+=1
                loss+=(p!=0 and p!=y)
                if loss > ub:
                    break
            else:
                raw=[sign(w[0]+w[1]*x) for x in xs]
                candidates.append(dict(w=w,ice_loss=loss,raw_predictions=raw,equation_1_loss=sum(p!=y for p,y in zip(raw,ys))))
    return sorted(candidates,key=lambda c:c['"'ice_loss']),scores

for name,xs,ys in [('boundary',[1.,2.],[-1,1]),('nearby',[1.,1.+1e-9,1.+2e-9],[1,-1,1])]:
    c,count=run_d1(xs,ys,len(xs))
    optimum=min(sum(y"'!=s*(-1 if i<k else 1) for i,y in enumerate(ys)) for k in range(len(xs)+1) for s in [-1,1])
    print(name,'"'first best:',c[0],'true optimum:',optimum)
print('D=1 all-positive sorted points, tight ub=0: N, number of scored points, retained loss')
for n in [10,20,40,80]:
    candidates,count=run_d1([float(x) for x in range(1,n+1)],[1]*n,0)
    print(n,count,candidates[0]['ice_loss'])
